Here is the root cause:
The bug occurs because when .mmap_prepare replaces the original file with a new one (e.g., for /dev/zero with MAP_SHARED, shmem_zero_setup_desc allocates a new shmem file), and the subsequent __mmap_new_vma() fails, the error path in __mmap_region() (at the abort_munmap label) does not release the new file. The original file is cleaned up by ksys_mmap_pgoff(), but the replacement file's reference is never decremented via fput(), leading to a memory leak. This was missed in the earlier fix (commit 605f6586ecf7) which only handled the success path by skipping get_file() but did not add the corresponding fput() on failure.

Here is the patch:

 static unsigned long __mmap_region(struct file *file, unsigned long addr,
 		unsigned long len, vm_flags_t vm_flags, unsigned long pgoff,
 		struct list_head *uf)
 {
 	struct mm_struct *mm = current->mm;
 	struct vm_area_struct *vma = NULL;
 	bool have_mmap_prepare = file && file->f_op->mmap_prepare;
 	VMA_ITERATOR(vmi, mm, addr);
 	MMAP_STATE(map, mm, &vmi, addr, len, pgoff, vm_flags, file);
 	struct vm_area_desc desc = {
 		.mm = mm,
 		.file = file,
 		.action = {
 			.type = MMAP_NOTHING, /* Default to no further action. */
 		},
 	};
 	bool allocated_new = false;
 	int error;

 	map.check_ksm_early = can_set_ksm_flags_early(&map);

 	error = __mmap_setup(&map, &desc, uf);
 	if (!error && have_mmap_prepare)
 		error = call_mmap_prepare(&map, &desc);
 	if (error)
 		goto abort_munmap;

 	if (map.check_ksm_early)
 		update_ksm_flags(&map);

 	/* Attempt to merge with adjacent VMAs... */
 	if (map.prev || map.next) {
 		VMG_MMAP_STATE(vmg, &map, /* vma = */ NULL);

 		vma = vma_merge_new_range(&vmg);
 	}

 	/* ...but if we can't, allocate a new VMA. */
 	if (!vma) {
 		error = __mmap_new_vma(&map, &vma);
 		if (error)
 			goto unacct_error;
 		allocated_new = true;
 	}

 	if (have_mmap_prepare)
 		set_vma_user_defined_fields(vma, &map);

 	__mmap_complete(&map, vma);

 	if (have_mmap_prepare && allocated_new) {
 		error = call_action_complete(&map, &desc, vma);

 		if (error)
 			return error;
 	}

 	return addr;

 	/* Accounting was done by __mmap_setup(). */
 unacct_error:
 	if (map.charged)
 		vm_unacct_memory(map.charged);
 abort_munmap:
+	/*
+	 * This indicates that .mmap_prepare has set a new file, differing from
+	 * desc->vm_file. But since we're aborting the operation, only the
+	 * original file will be cleaned up. Ensure we clean up both.
+	 */
+	if (map.file_doesnt_need_get)
+		fput(map.file);
 	vms_abort_munmap_vmas(&map.vms, &map.mas_detach);
 	return error;
 }



